import time

def onbellekle(ttl=None, saat=time.monotonic):
    def dekorator(f):
        cache = {}
        isabet = 0
        iska = 0

        def sarmal(*args, **kwargs):
            nonlocal isabet, iska
            # Create a stable key for args and kwargs
            key_parts = list(args)
            for k in sorted(kwargs.items()):
                key_parts.append(k)
            try:
                anahtar = tuple(key_parts)
            except TypeError:
                # If unhashable (like a list), don't cache
                iska += 1
                return f(*args, **kwargs)

            if anahtar in cache:
                deger, zaman = cache[anahtar]
                if ttl is None or saat() - zaman <= ttl: # Fixed logic for TTL
                    isabet += 1
                    return deger

            iska += 1
            deger = f(*args, **kwargs)
            cache[anahtar] = (deger, saat())
            return deger

        def temizle():
            cache.clear()

        def bilgi():
            return {"isabet": isabet, "iska": iska}

        sarmal.temizle = temizle
        sarmal.bilgi = bilgi
        # Preserve name and docstring
        sarmal.__name__ = f.__name__
        sarmal.__doc__ = f.__doc__
        return sarmal
    return dekorator

# Test logic manually to verify fix before writing file
def test_logic():
    cagri = []
    @onbellekle()
    def kare(x):
        """Karesini alır."""
        cagri.append(x)
        return x * x

    assert kare(3) == 9 and kare(3) == 9 and cagri == [3], "temel önbellek"
    assert kare.bilgi() == {"isabet": 1, "iska": 1}, f"bilgi: {kare.bilgi()}"

    @onbellekle()
    def us(x, n=2):
        return x ** n

    # The failing test in original code was likely due to kwargs not being part of the key
    assert us(2, n=3) == 8 and us(2, n=4) == 16, f"isimli argümanlar: {us(2, n=3)=}, {us(2, n=4)=}"
    assert kare.__name__ == "kare", "fonksiyon adı korunmalı"
